def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                cells.setdefault(grid[r][c], set()).add((r, c))

    frames = []
    frame_cells = set()

    for color, pts in cells.items():
        rs = [r for r, c in pts]
        cs = [c for r, c in pts]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue

        border = {
            (r, c)
            for r in range(r0, r1 + 1)
            for c in range(c0, c1 + 1)
            if r in (r0, r1) or c in (c0, c1)
        }
        if pts == border:
            frames.append((color, r0, r1, c0, c1, border))
            frame_cells |= border

    loose_counts = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r, c) not in frame_cells:
                loose_counts[color] = loose_counts.get(color, 0) + 1

    out = [[0] * w for _ in range(h)]
    for color, r0, r1, c0, c1, border in frames:
        for r, c in border:
            out[r][c] = color

        interior = [
            (r, c)
            for r in range(r0 + 1, r1)
            for c in range(c0 + 1, c1)
            if ((r - (r0 + 1)) + (c - (c0 + 1))) % 2 == 0
        ]
        count = len(interior)
        fill_color = next(
            (color for color, n in loose_counts.items() if n == count),
            None
        )
        if fill_color is not None:
            for r, c in interior:
                out[r][c] = fill_color

    return out
